import { getAllProducts } from '@/lib/db';
import { revalidateTag, cacheTag } from 'next/cache';

interface Product {
  id: number;
  name: string;
  price: number;
}

async function getCachedProducts() {
  'use cache';
  cacheTag('products');
  return (await getAllProducts()) as Product[];
}

async function ProductList() {
  const products = await getCachedProducts();

  return (
    <div className="border p-4 rounded-md shadow-sm">
      <h2 className="text-xl font-bold mb-4">Product List</h2>
      <ul className="space-y-2">
        {products.map((product) => (
          <li key={product.id} className="flex justify-between border-b pb-2 last:border-0">
            <span>{product.name}</span>
            <span className="font-semibold">${product.price}</span>
          </li>
        ))}
      </ul>
      <p className="text-xs text-gray-500 mt-4">
        Fetched at: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

export default function Page() {
  async function invalidateProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="p-8 max-w-2xl mx-auto font-sans">
      <h1 className="text-2xl font-bold mb-6">Efficient Data Caching</h1>

      <div className="space-y-6">
        <ProductList />

        <div className="bg-gray-50 p-4 rounded-md">
          <h3 className="font-medium mb-2">Cache Control</h3>
          <p className="text-sm text-gray-600 mb-4">
            Submitting this form will invalidate the "products" cache tag, causing the data to be re-fetched on the next request.
          </p>
          <form action={invalidateProducts}>
            <button 
              type="submit"
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm transition-colors"
            >
              Invalidate Cache
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

